    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endRFL(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // RFL_ID
        $builder->required($o, 10);  // LINKS
        $builder->required($o, 14);  // SAMPLE_LINK_INDEXES
        $builder->required($o, 16);  // SAMPLE_EPOCHS
        $builder->required($o, 98);  // PROVENANCE
        return $o;
    }

    public static function finishRFLBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$RFL");
    }
